-- Generated files (designers, source generators' output, assembly info,
-- anything headed <auto-generated> or Go's "Code generated ... DO NOT EDIT")
-- are indexed as text, as tests are: no symbols or imports, so no part of the
-- import graph or the wiki's plan, and ranked lower by search. Files stored
-- before this version count as written by hand until their repository's next
-- index, which copies no file's rows from a snapshot an older analyzer read:
-- each is read again, so C#, Java and Rust files get their symbols too.
ALTER TABLE source_files ADD COLUMN generated INTEGER NOT NULL DEFAULT 0;
ALTER TABLE snapshots ADD COLUMN analyzer INTEGER NOT NULL DEFAULT 0;
